#define MAX_SIZE 1000000
#define MOD1 998244353
#define MOD2 1000000007
#define long_long long long
#define decrement(x) (!(x--)&&(x+=MOD2))
using namespace std;

long long n, nn, p;
int answer, count_digits[7], count_array[7][7], sum_array[7][7][MAX_SIZE+1];

void initialize(int x, int length, const_ref int& k) {
    sum_array[k][length][++count_array[k][length]] = (++p) - x;
    if (length == k) return;
    for (int i = 0; i <= 9; ++i) initialize(x * 10 + i, length + 1, k);
