void brute_force(long long x, int length) {
    if (x > n) return;
    ++p;
    answer = (answer + (p - x) / MOD1 - (p < x) + MOD2) % MOD2;
    for (int i = 0; i <= 9; ++i) brute_force(x * 10 + i, length + 1);
}

void solve(int x, int length) {
    if (length != 6) {
        ++p;
        answer = (answer + (p - x) / MOD1 - (p < x) + MOD2) % MOD2;
        for (int i = 0; i <= 9; ++i) solve(x * 10 + i, length + 1);
        return;
    }
    if (x == nn) return brute_force(x, 0);
    int k; long long v;
    for (k = 0, v = x; k <= 6 && v <= n; ++k, v *= 10);
    --k;
    for (int i = 0; i <= k; ++i) {
        v = p - 1LL * x * count_digits[i];
        answer = (answer + 1LL * (v / MOD1 - (v < 0) + MOD2) * count_digits[i]) % MOD2;
        v = (v % MOD1 + MOD1) % MOD1;
        answer = (answer + count_digits[i] - (lower_bound(sum_array[k][i] + 1, sum_array[k][i] + count_digits[i] + 1, v) - sum_array[k][i]) + 1) % MOD2;
    }
    for (int i = 0; i <= k; ++i) p += count_digits[i];
}

int main() {
