    scanf("%lld", &n);
    count_digits[0] = i = 1;
    for (k = 1; k <= 6; ++k) count_digits[k] = count_digits[k - 1] * 10;
    for (k = 0; k <= 6; ++k) {
        p = 0;
        initialize(0, 0, k);
        for (i = 0; i <= k; ++i) {
